import{_ as r,o as n,c as a,ae as i}from"./chunks/framework.Cqu5Y2mC.js";const c=JSON.parse('{"title":"Projektdokumentation","description":"","frontmatter":{},"headers":[],"relativePath":"01-Betrieb/24.04.2026.md","filePath":"01-Betrieb/24.04.2026.md"}'),t={name:"01-Betrieb/24.04.2026.md"};function s(u,e,d,l,o,h){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="projektdokumentation" tabindex="-1">Projektdokumentation <a class="header-anchor" href="#projektdokumentation" aria-label="Permalink to &quot;Projektdokumentation&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>Im Rahmen unseres Projekts haben wir heute Anpassungen an der Infrastruktur vorgenommen sowie eine sicherere Verbindungsstrategie definiert.</p><h2 id="anderungen-am-infrastrukturdiagramm" tabindex="-1">Änderungen am Infrastrukturdiagramm <a class="header-anchor" href="#anderungen-am-infrastrukturdiagramm" aria-label="Permalink to &quot;Änderungen am Infrastrukturdiagramm&quot;">​</a></h2><p>Das bestehende Infrastrukturdiagramm wurde im <strong>Mermaid Live Editor</strong> überarbeitet und aktualisiert.</p><h3 id="details" tabindex="-1">Details: <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details:&quot;">​</a></h3><ul><li>Anpassung der Netzwerkstruktur</li><li>Aktualisierung der Komponenten und deren Verbindungen</li><li>Verbesserte Visualisierung der Datenflüsse</li></ul><p>Das Diagramm dient nun als aktuelle Referenz für die Systemarchitektur.</p><h2 id="registrierung-des-gateway" tabindex="-1">Registrierung des Gateway <a class="header-anchor" href="#registrierung-des-gateway" aria-label="Permalink to &quot;Registrierung des Gateway&quot;">​</a></h2><p>Zusätzlich wurde ein <strong>Apollonsensor im Gateway</strong> erfolgreich registriert.</p><h3 id="details-1" tabindex="-1">Details: <a class="header-anchor" href="#details-1" aria-label="Permalink to &quot;Details:&quot;">​</a></h3><ul><li>Einrichtung und Einbindung des Gateways in die bestehende Infrastruktur</li><li>Sicherstellung der Kommunikation zwischen Gateway und System</li><li>Vorbereitung für die Verarbeitung von Sensordaten</li></ul><h2 id="entscheidung-zur-verbindungsstrategie" tabindex="-1">Entscheidung zur Verbindungsstrategie <a class="header-anchor" href="#entscheidung-zur-verbindungsstrategie" aria-label="Permalink to &quot;Entscheidung zur Verbindungsstrategie&quot;">​</a></h2><h3 id="ausgangssituation" tabindex="-1">Ausgangssituation <a class="header-anchor" href="#ausgangssituation" aria-label="Permalink to &quot;Ausgangssituation&quot;">​</a></h3><p>Ursprünglich war geplant, einen Webserver mit Nginx zu verwenden, um den Zugriff und die Kommunikation zu steuern.</p><h3 id="neue-entscheidung" tabindex="-1">Neue Entscheidung <a class="header-anchor" href="#neue-entscheidung" aria-label="Permalink to &quot;Neue Entscheidung&quot;">​</a></h3><p>Stattdessen haben wir uns für die Nutzung eines <strong>Tunnels</strong> entschieden.</p><h3 id="grunde-fur-die-anderung" tabindex="-1">Gründe für die Änderung: <a class="header-anchor" href="#grunde-fur-die-anderung" aria-label="Permalink to &quot;Gründe für die Änderung:&quot;">​</a></h3><ul><li><strong>Erhöhte Sicherheit</strong> bei der Nutzung von WLAN-Netzwerken</li><li>Reduzierung der Angriffsfläche im Vergleich zu einem öffentlich erreichbaren Server</li><li>Einfachere und sicherere Verbindung zwischen Client und Server</li></ul><h3 id="ergebnis" tabindex="-1">Ergebnis: <a class="header-anchor" href="#ergebnis" aria-label="Permalink to &quot;Ergebnis:&quot;">​</a></h3><p>Die Verbindung erfolgt nun über einen gesicherten Tunnel, wodurch die Datenübertragung besser geschützt ist.</p><h2 id="fazit" tabindex="-1">Fazit <a class="header-anchor" href="#fazit" aria-label="Permalink to &quot;Fazit&quot;">​</a></h2><p>Durch die Anpassung des Infrastrukturdiagramms, die Registrierung des Gateways und die Umstellung auf eine Tunnel-basierte Verbindung konnten wir die Sicherheit und Klarheit unserer Systemarchitektur verbessern.</p><p>p.s. Tunnel noch nicht realisiert, wird erstmal durch https mit benutzername und passwort funktionieren.</p>',24)])])}const m=r(t,[["render",s]]);export{c as __pageData,m as default};
